  const displayName=String(body?.displayName||"").trim().slice(0,120);
  const businessName=String(body?.businessName||"").trim().slice(0,160);
  const onboarding=body?.onboarding&&typeof body.onboarding==="object"?body.onboarding:{};
  const referralCode=String(body?.referralCode||"").trim().toUpperCase().slice(0,16);

  if(!validEmail(email))return NextResponse.json({error:"Проверь email."},{status:400});
  if(password.length<8)return NextResponse.json({error:"Пароль должен быть не короче 8 символов."},{status:400});
  if(!displayName)return NextResponse.json({error:"Укажи имя."},{status:400});
  if(role==="business"&&(!businessName||onboarding?.ageGroup!=="18+")){
    return NextResponse.json({error:"Для бизнес-аккаунта нужно название компании и возраст 18+."},{status:400});
  }

  const site=process.env.NEXT_PUBLIC_SITE_URL||"https://getedita.app";
  const metadata={
    role,
    display_name:displayName,
    business_name:role==="business"?businessName:undefined,
    onboarding:{...onboarding,role},
    accepted_terms:true,
    accepted_personal_data:true,
    terms_version:"2026-09-12",
    privacy_version:"2026-09-12"
  };

  const {data,error}=await service.auth.admin.generateLink({
    type:"signup",
    email,
    password,
    options:{
      data:metadata,
      redirectTo:site+"/platform"
    }
  });

  if(error){
    const msg=error.message.toLowerCase();
    if(msg.includes("already")||msg.includes("registered")){
      return NextResponse.json({error:"Аккаунт с таким email уже существует. Попробуй войти или восстановить пароль."},{status:409});
    }
    return NextResponse.json({error:"Не удалось создать аккаунт: "+error.message},{status:400});
  }

  const createdUserId=(data as any)?.user?.id;
  if(role==="editor"&&referralCode&&createdUserId){
    const {data:referrer}=await service.from("profiles")
      .select("id,referral_code")
      .eq("referral_code",referralCode)
      .maybeSingle();
    if(referrer?.id&&referrer.id!==createdUserId){
      await service.from("referrals").upsert({
        referrer_id:referrer.id,
        referred_id:createdUserId,
        referral_code:referralCode,
        status:"pending"
      },{onConflict:"referred_id"});
    }
  }

  const link=(data as any)?.properties?.action_link||(data as any)?.properties?.actionLink;
  if(!link)return NextResponse.json({error:"Не удалось создать ссылку подтверждения."},{status:500});

  try{
    await sendTransactionalEmail({
      to:email,
      subject:"Подтверди email в EDITA",
      html:authEmailHtml(
        "Подтверди email",
        "Нажми кнопку ниже, чтобы подтвердить адрес и открыть свой аккаунт EDITA.",
        "Подтвердить email",
        link
      ),
      text:"Подтверди email EDITA: "+link
    });
  }catch(e){
    if(createdUserId){
      const {error:cleanupError}=await service.auth.admin.deleteUser(createdUserId);
      if(cleanupError)console.error("Could not clean up user after confirmation email failure",{code:cleanupError.code||"supabase_cleanup_failed"});
    }
    const code=e instanceof Error?e.message:"EMAIL_SEND_FAILED";
    return NextResponse.json({
      error:code==="RESEND_NOT_CONFIGURED"
        ?"Почтовый сервис EDITA ещё не подключён."
        :code==="RESEND_INVALID_KEY_FORMAT"
          ?"Ключ почтового сервиса настроен неверно."
        :"Не удалось отправить письмо подтверждения. Попробуй позже."
    },{status:503});
  }

  return NextResponse.json({ok:true,email});
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){const h=req.headers.get("authorization");return h?.startsWith("Bearer ")?h.slice(7):null}

async function league(service:any){
  const {data:businesses}=await service.from("businesses")
    .select("id,name,verified,verification_level")
    .eq("verified",true);

  const rows=await Promise.all((businesses||[]).map(async(b:any)=>{
    const [{data:challenges},{data:jobs},{data:reviews}]=await Promise.all([
      service.from("challenges").select("id,status").eq("business_id",b.id),
      service.from("jobs").select("id,status").eq("business_id",b.id),
      service.from("business_reviews").select("brief_clarity,communication,fairness").eq("business_id",b.id)
    ]);
    const challengeIds=(challenges||[]).map((c:any)=>c.id);
    const {data:subs}=challengeIds.length
      ? await service.from("challenge_submissions").select("id,status").in("challenge_id",challengeIds)
      : {data:[] as any[]};
    const challengeCount=Math.min((challenges||[]).length,5);
    const jobCount=Math.min((jobs||[]).length,5);
    const submissionCount=Math.min((subs||[]).length,20);
    const winnerCount=Math.min((subs||[]).filter((s:any)=>s.status==="winner").length,5);
    const verifyBonus=b.verification_level==="partner"?300:b.verification_level==="popular_brand"?220:150;
    const reviewCount=(reviews||[]).length;
    const reviewAvg=reviewCount
      ? (reviews||[]).reduce((sum:number,r:any)=>sum+(Number(r.brief_clarity)+Number(r.communication)+Number(r.fairness))/3,0)/reviewCount
      : null;
    const reviewBonus=reviewCount>=3?Math.round((reviewAvg||0)*20):0;
    const points=verifyBonus+challengeCount*35+jobCount*20+submissionCount*4+winnerCount*100+reviewBonus;
    return {
      id:b.id,name:b.name,verification_level:b.verification_level,points,
      challenges:(challenges||[]).length,jobs:(jobs||[]).length,submissions:(subs||[]).length,winners:winnerCount,
      review_count:reviewCount,review_rating:reviewAvg==null?null:Math.round(reviewAvg*10)/10
    };
  }));
  return rows.sort((a:any,b:any)=>b.points-a.points);
}

export async function GET(req:NextRequest){
  const service=getSupabaseServiceClient();
  if(!service)return NextResponse.json({error:"Сервис недоступен."},{status:503});
  const board=await league(service);

  const user=await getUserFromAccessToken(token(req));
  let mine=null,talent:any[]=[];
  if(user){
    const {data:business}=await service.from("businesses").select("id,name,verified,verification_level").eq("owner_id",user.id).maybeSingle();
    if(business){
      mine=board.find((b:any)=>b.id===business.id)||{...business,points:0,challenges:0,jobs:0,submissions:0,winners:0};
      const {data:saved}=await service.from("business_saved_editors").select("editor_id,note,created_at").eq("business_id",business.id).order("created_at",{ascending:false});
      const ids=(saved||[]).map((s:any)=>s.editor_id);
      const {data:profiles}=ids.length?await service.from("public_profiles").select("id,username,display_name,level,xp,rating_points,ai_score").in("id",ids):{data:[] as any[]};
      const map=Object.fromEntries((profiles||[]).map((p:any)=>[p.id,p]));
      talent=(saved||[]).map((s:any)=>({...s,profile:map[s.editor_id]||null}));
    }
  }

  return NextResponse.json({season:"EDITA Brand League · Осень 2026",leaderboard:board.slice(0,20),mine,talent});
}

export async function POST(req:NextRequest){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход."},{status:401});
  const {data:business}=await service.from("businesses").select("id,verified").eq("owner_id",user.id).maybeSingle();
  if(!business)return NextResponse.json({error:"Бизнес-профиль не найден."},{status:404});

  const body=await req.json().catch(()=>({}));
  const action=String(body?.action||"");

  if(action==="save_editor"){
    const username=String(body?.username||"").trim().replace(/^@/,"").toLowerCase();
    const {data:editor}=await service.from("public_profiles").select("id,username").ilike("username",username).maybeSingle();
    if(!editor)return NextResponse.json({error:"Монтажёр с таким @username не найден."},{status:404});
    const {error}=await service.from("business_saved_editors").upsert({
      business_id:business.id,editor_id:editor.id,note:String(body?.note||"").trim().slice(0,500)||null
    },{onConflict:"business_id,editor_id"});
    if(error)return NextResponse.json({error:error.message},{status:400});
    return NextResponse.json({ok:true});
  }

  if(action==="remove_editor"){
    const editorId=String(body?.editorId||"");
    await service.from("business_saved_editors").delete().eq("business_id",business.id).eq("editor_id",editorId);
    return NextResponse.json({ok:true});
  }

  return NextResponse.json({error:"Неизвестное действие."},{status:400});
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function tokenFrom(req:NextRequest){
  const bearer=req.headers.get("authorization");
  return bearer?.startsWith("Bearer ")?bearer.slice(7):null;
}

export async function GET(req:NextRequest){
  const user=await getUserFromAccessToken(tokenFrom(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  const {data:profile}=await service.from("profiles").select("role").eq("id",user.id).maybeSingle();
  if(profile?.role!=="business")return NextResponse.json({error:"Раздел доступен бизнес-аккаунту."},{status:403});

  let {data:business}=await service.from("businesses")
    .select("id,name,verified,verification_status,verification_level,verification_note,verified_at")
    .eq("owner_id",user.id).maybeSingle();

  if(!business){
    const name=(user.user_metadata?.display_name||user.email?.split("@")[0]||"Business")+" Studio";
    const {data:created,error}=await service.from("businesses")
      .upsert({owner_id:user.id,name},{onConflict:"owner_id"})
      .select("id,name,verified,verification_status,verification_level,verification_note,verified_at")
      .single();
    if(error)return NextResponse.json({error:error.message},{status:500});
    business=created;
  }

  const {data:request}=await service.from("business_verification_requests")
    .select("id,requested_level,legal_name,inn,registration_number,website_url,social_url,reported_audience,status,review_note,created_at,reviewed_at")
    .eq("business_id",business.id)
    .order("created_at",{ascending:false})
    .limit(1)
    .maybeSingle();

  return NextResponse.json({business,request:request||null});
}

export async function POST(req:NextRequest){
  const user=await getUserFromAccessToken(tokenFrom(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  const {data:profile}=await service.from("profiles").select("role").eq("id",user.id).maybeSingle();
  if(profile?.role!=="business")return NextResponse.json({error:"Раздел доступен бизнес-аккаунту."},{status:403});

  const body=await req.json();
  const requestedLevel=body?.requestedLevel==="popular_brand"?"popular_brand":"verified_company";
  const legalName=String(body?.legalName||"").trim().slice(0,180);
  const inn=String(body?.inn||"").replace(/\D/g,"").slice(0,12);
  const registrationNumber=String(body?.registrationNumber||"").replace(/\D/g,"").slice(0,15);
  const websiteUrl=String(body?.websiteUrl||"").trim().slice(0,500);
  const socialUrl=String(body?.socialUrl||"").trim().slice(0,500);
  const reportedAudience=body?.reportedAudience?Math.max(0,Math.floor(Number(body.reportedAudience))):null;
  const documentPaths=Array.isArray(body?.documentPaths)
    ? body.documentPaths.filter((v:any)=>typeof v==="string"&&v.startsWith(user.id+"/")).slice(0,3)
    : [];

  if(!legalName)return NextResponse.json({error:"Напиши официальное название компании или ИП."},{status:400});
  if(!inn&&!registrationNumber)return NextResponse.json({error:"Укажи ИНН или ОГРН / ОГРНИП."},{status:400});
  if(inn&&![10,12].includes(inn.length))return NextResponse.json({error:"ИНН должен состоять из 10 или 12 цифр."},{status:400});
  if(registrationNumber&&![13,15].includes(registrationNumber.length))return NextResponse.json({error:"ОГРН обычно содержит 13 цифр, ОГРНИП — 15."},{status:400});
  if(documentPaths.length===0)return NextResponse.json({error:"Добавь хотя бы один документ для проверки."},{status:400});
  if(requestedLevel==="popular_brand"&&!websiteUrl&&!socialUrl){
    return NextResponse.json({error:"Для отметки «Известный бренд» добавь сайт или публичную страницу бренда."},{status:400});
  }

  let {data:business}=await service.from("businesses").select("id").eq("owner_id",user.id).maybeSingle();
  if(!business){
    const name=(user.user_metadata?.display_name||legalName||"Business")+" Studio";
    const created=await service.from("businesses").upsert({owner_id:user.id,name},{onConflict:"owner_id"}).select("id").single();
    if(created.error)return NextResponse.json({error:created.error.message},{status:500});
    business=created.data;
  }

  const {data:request,error}=await service.from("business_verification_requests").insert({
    business_id:business.id,
    created_by:user.id,
    requested_level:requestedLevel,
    legal_name:legalName,
    inn:inn||null,
    registration_number:registrationNumber||null,
    website_url:websiteUrl||null,
    social_url:socialUrl||null,
    reported_audience:reportedAudience,
    document_paths:documentPaths,
    status:"pending"
  }).select("id,status,requested_level,created_at").single();

  if(error)return NextResponse.json({error:error.message},{status:500});

  await service.from("businesses")
    .update({verification_status:"pending",verification_note:null})
    .eq("id",business.id);

  return NextResponse.json({ok:true,request});
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){const v=req.headers.get("authorization");return v?.startsWith("Bearer ")?v.slice(7):null}

async function auth(req:NextRequest){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return null;
  const {data:profile}=await service.from("profiles")
    .select("id,role,display_name,username,onboarding,guardian_verified")
    .eq("id",user.id).maybeSingle();
  if(!profile)return null;
  return {user,service,profile};
}

async function league(service:any){
  const {data:businesses}=await service.from("businesses")
    .select("id,name,verified,verification_level")
    .eq("verified",true);
  const rows=[];
  for(const b of businesses||[]){
    const [{count:campaigns},{count:applications},{count:challenges},{count:jobs}]=await Promise.all([
      service.from("business_campaigns").select("id",{count:"exact",head:true}).eq("business_id",b.id).eq("status","open"),
      service.from("business_campaign_applications").select("id,business_campaigns!inner(business_id)",{count:"exact",head:true}).eq("business_campaigns.business_id",b.id),
      service.from("challenges").select("id",{count:"exact",head:true}).eq("business_id",b.id),
      service.from("jobs").select("id",{count:"exact",head:true}).eq("business_id",b.id)
    ]);
    const score=(campaigns||0)*15+(applications||0)*2+(challenges||0)*10+(jobs||0)*5;
    rows.push({id:b.id,name:b.name,verification_level:b.verification_level,score,campaigns:campaigns||0,applications:applications||0});
  }
  rows.sort((a,b)=>b.score-a.score);
  return rows.slice(0,20);
}

export async function GET(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  if(a.profile.role==="business"){
    const {data:business}=await a.service.from("businesses").select("id,name,verified,verification_level").eq("owner_id",a.user.id).maybeSingle();
    const {data:campaigns}=business?await a.service.from("business_campaigns").select("*").eq("business_id",business.id).order("created_at",{ascending:false}):{data:[] as any[]};
    const ids=(campaigns||[]).map((c:any)=>c.id);
    const {data:apps}=ids.length?await a.service.from("business_campaign_applications")
      .select("id,campaign_id,editor_id,portfolio_url,note,status,created_at").in("campaign_id",ids).order("created_at",{ascending:false}):{data:[] as any[]};
    const editorIds=[...new Set((apps||[]).map((x:any)=>x.editor_id))];
    const {data:editors}=editorIds.length?await a.service.from("profiles").select("id,display_name,username").in("id",editorIds):{data:[] as any[]};
    const map=Object.fromEntries((editors||[]).map((p:any)=>[p.id,p]));
    return NextResponse.json({
      mode:"business",
      business,
      campaigns:(campaigns||[]).map((c:any)=>({...c,applications:(apps||[]).filter((x:any)=>x.campaign_id===c.id).map((x:any)=>({...x,editor:map[x.editor_id]}))})),
      league:await league(a.service)
    });
  }

  const {data:campaignRows}=await a.service.from("business_campaigns")
    .select("*").eq("status","open").order("created_at",{ascending:false});
  const businessIds=[...new Set((campaignRows||[]).map((c:any)=>c.business_id))];
  const {data:businesses}=businessIds.length?await a.service.from("businesses")
    .select("id,name,verified,verification_level").in("id",businessIds).eq("verified",true):{data:[] as any[]};
  const map=Object.fromEntries((businesses||[]).map((b:any)=>[b.id,b]));
  const visible=(campaignRows||[]).filter((c:any)=>map[c.business_id]).map((c:any)=>({...c,business:map[c.business_id]}));
  const {data:ownApps}=await a.service.from("business_campaign_applications").select("campaign_id,status").eq("editor_id",a.user.id);
  const ownMap=Object.fromEntries((ownApps||[]).map((x:any)=>[x.campaign_id,x.status]));

  return NextResponse.json({
    mode:"editor",
    campaigns:visible.map((c:any)=>({...c,myStatus:ownMap[c.id]||null})),
    league:await league(a.service)
  });
}

export async function POST(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});
  const body=await req.json().catch(()=>({}));
  const action=String(body?.action||"");

  if(action==="create"){
    if(a.profile.role!=="business")return NextResponse.json({error:"Нужен бизнес-аккаунт."},{status:403});
    const {data:business}=await a.service.from("businesses").select("id,verified").eq("owner_id",a.user.id).maybeSingle();
    if(!business?.verified)return NextResponse.json({error:"Сначала пройди проверку компании."},{status:403});

    const title=String(body?.title||"").trim().slice(0,120);
    const goal=String(body?.goal||"").trim().slice(0,500);
    const requirements=String(body?.requirements||"").trim().slice(0,2000);
    const budgetText=String(body?.budgetText||"").trim().slice(0,120);
    const creatorSlots=Math.max(1,Math.min(100,Number(body?.creatorSlots)||1));
    const contentTypes=Array.isArray(body?.contentTypes)?body.contentTypes.map((x:any)=>String(x).slice(0,40)).slice(0,8):[];
    if(title.length<3||goal.length<3)return NextResponse.json({error:"Добавь название и понятную цель кампании."},{status:400});
    if(!budgetText)return NextResponse.json({error:"Укажи бюджет или понятные условия оплаты."},{status:400});

    const {data,error}=await a.service.from("business_campaigns").insert({
      business_id:business.id,title,goal,requirements,budget_text:budgetText,
      creator_slots:creatorSlots,content_types:contentTypes,status:"open",
      ends_at:body?.endsAt||null
    }).select("*").single();
    if(error)return NextResponse.json({error:error.message},{status:500});
    return NextResponse.json({ok:true,campaign:data});
  }

  if(action==="apply"){
    if(a.profile.role!=="editor")return NextResponse.json({error:"Нужен аккаунт монтажёра."},{status:403});
    const age=a.profile.onboarding?.ageGroup||"18+";
    if(age!=="18+"&&!a.profile.guardian_verified)return NextResponse.json({error:"Для коммерческой кампании сначала нужно подтверждение родителя."},{status:403});

    const campaignId=String(body?.campaignId||"");
    const {data:campaign}=await a.service.from("business_campaigns")
      .select("id,status,business_id").eq("id",campaignId).maybeSingle();
    if(!campaign||campaign.status!=="open")return NextResponse.json({error:"Кампания уже закрыта."},{status:404});
    const {data:b}=await a.service.from("businesses").select("verified").eq("id",campaign.business_id).maybeSingle();
    if(!b?.verified)return NextResponse.json({error:"Компания ещё не подтверждена."},{status:403});

    const {error}=await a.service.from("business_campaign_applications").upsert({
      campaign_id:campaignId,editor_id:a.user.id,
      portfolio_url:String(body?.portfolioUrl||"").trim().slice(0,500)||null,
      note:String(body?.note||"").trim().slice(0,1000)||null,
      status:"applied"
    },{onConflict:"campaign_id,editor_id"});
    if(error)return NextResponse.json({error:error.message},{status:500});
    return NextResponse.json({ok:true});
  }

  if(action==="application_status"){
    if(a.profile.role!=="business")return NextResponse.json({error:"Нужен бизнес-аккаунт."},{status:403});
    const id=String(body?.applicationId||"");
    const status=String(body?.status||"");
    if(!["shortlisted","accepted","declined"].includes(status))return NextResponse.json({error:"Недопустимый статус."},{status:400});

    const {data:app}=await a.service.from("business_campaign_applications").select("id,campaign_id").eq("id",id).maybeSingle();
    if(!app)return NextResponse.json({error:"Отклик не найден."},{status:404});
    const {data:campaign}=await a.service.from("business_campaigns").select("business_id").eq("id",app.campaign_id).maybeSingle();
    const {data:business}=campaign?await a.service.from("businesses").select("owner_id").eq("id",campaign.business_id).maybeSingle():{data:null};
    if(!business||business.owner_id!==a.user.id)return NextResponse.json({error:"Нет доступа."},{status:403});
    await a.service.from("business_campaign_applications").update({status}).eq("id",id);
    return NextResponse.json({ok:true});
  }

  return NextResponse.json({error:"Неизвестное действие."},{status:400});
}

