import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){
  const h=req.headers.get("authorization");
  return h?.startsWith("Bearer ")?h.slice(7):null;
}
async function auth(req:NextRequest){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  return user&&service?{user,service}:null;
}
function ageBand(profile:any){return profile?.onboarding?.ageGroup||"18+"}

export async function GET(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});
  const search=(req.nextUrl.searchParams.get("search")||"").trim().replace(/^@/,"").toLowerCase();

  if(search){
    const {data}=await a.service.from("public_profiles")
      .select("id,username,display_name,level,xp,rating_points")
      .ilike("username",search)
      .neq("id",a.user.id)
      .limit(8);
    return NextResponse.json({results:data||[]});
  }

  const {data:rels,error}=await a.service.from("friendships")
    .select("id,requester_id,addressee_id,status,created_at")
    .or("requester_id.eq."+a.user.id+",addressee_id.eq."+a.user.id)
    .order("created_at",{ascending:false});
  if(error)return NextResponse.json({error:error.message},{status:500});

  const ids=[...new Set((rels||[]).flatMap((r:any)=>[r.requester_id,r.addressee_id]).filter((id:string)=>id!==a.user.id))];
  const {data:profiles}=ids.length
    ? await a.service.from("public_profiles").select("id,username,display_name,level,xp,rating_points").in("id",ids)
    : {data:[] as any[]};
  const map=Object.fromEntries((profiles||[]).map((p:any)=>[p.id,p]));

  return NextResponse.json({
    relations:(rels||[]).map((r:any)=>({
      ...r,
      direction:r.requester_id===a.user.id?"outgoing":"incoming",
      other:map[r.requester_id===a.user.id?r.addressee_id:r.requester_id]||null
    }))
  });
}

export async function POST(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});
  const body=await req.json().catch(()=>({}));
  const action=String(body?.action||"");

  if(action==="send"){
    const username=String(body?.username||"").trim().replace(/^@/,"").toLowerCase();
    const {data:target}=await a.service.from("public_profiles").select("id,username").ilike("username",username).maybeSingle();
    if(!target||target.id===a.user.id)return NextResponse.json({error:"Пользователь не найден."},{status:404});

    const [{data:me},{data:them}]=await Promise.all([
      a.service.from("profiles").select("onboarding").eq("id",a.user.id).maybeSingle(),
      a.service.from("profiles").select("onboarding").eq("id",target.id).maybeSingle()
    ]);
    if(ageBand(me)!==ageBand(them)){
      return NextResponse.json({error:"Для безопасности дружба доступна только между аккаунтами одной возрастной группы."},{status:403});
    }

    const [low,high]=a.user.id<target.id?[a.user.id,target.id]:[target.id,a.user.id];
    const {data:existing}=await a.service.from("friendships")
      .select("id,status,requester_id,addressee_id")
      .or(`and(requester_id.eq.${low},addressee_id.eq.${high}),and(requester_id.eq.${high},addressee_id.eq.${low})`)
      .maybeSingle();
    if(existing)return NextResponse.json({ok:true,existing});

    const {data,error}=await a.service.from("friendships").insert({
      requester_id:a.user.id,
      addressee_id:target.id,
      status:"pending"
    }).select("id,status").single();
    if(error)return NextResponse.json({error:error.message},{status:400});
    return NextResponse.json({ok:true,relation:data});
  }

  const id=String(body?.id||"");
  const {data:rel}=await a.service.from("friendships").select("*").eq("id",id).maybeSingle();
  if(!rel)return NextResponse.json({error:"Запрос не найден."},{status:404});

  if(action==="accept"||action==="decline"){
    if(rel.addressee_id!==a.user.id||rel.status!=="pending")return NextResponse.json({error:"Нет доступа."},{status:403});
    const status=action==="accept"?"accepted":"declined";
    const {error}=await a.service.from("friendships").update({status,responded_at:new Date().toISOString()}).eq("id",id);
    if(error)return NextResponse.json({error:error.message},{status:500});
    return NextResponse.json({ok:true,status});
  }

  if(action==="cancel"){
    if(rel.requester_id!==a.user.id||rel.status!=="pending")return NextResponse.json({error:"Нет доступа."},{status:403});
    await a.service.from("friendships").delete().eq("id",id);
    return NextResponse.json({ok:true});
  }

  return NextResponse.json({error:"Неизвестное действие."},{status:400});
}

import {NextRequest,NextResponse} from "next/server";
import {createGroupAiReply,moderateGroupMessage} from "@/lib/content-moderation";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){
  const header=req.headers.get("authorization");
  return header?.startsWith("Bearer ")?header.slice(7):null;
}

async function access(req:NextRequest,groupId:string){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return null;
  const {data:member}=await service.from("study_group_members")
    .select("member_role")
    .eq("group_id",groupId)
    .eq("user_id",user.id)
    .maybeSingle();
  return member?{user,service}:null;
}

async function messages(service:any,groupId:string){
  const {data,error}=await service.from("group_messages")
    .select("id,author_id,sender_kind,content,created_at")
    .eq("group_id",groupId)
    .eq("status","published")
    .order("created_at",{ascending:false})
    .limit(80);
  if(error)throw error;
  const rows=(data||[]).reverse();
  const authorIds=Array.from(new Set(rows.map((row:any)=>row.author_id).filter(Boolean))) as string[];
  const {data:profiles}=authorIds.length
    ?await service.from("public_profiles").select("id,username,display_name").in("id",authorIds)
    :{data:[]};
  const profileMap=Object.fromEntries((profiles||[]).map((profile:any)=>[profile.id,profile]));
  return rows.map((row:any)=>({
    id:row.id,
    senderKind:row.sender_kind,
    content:row.content,
    createdAt:row.created_at,
    author:row.sender_kind==="ai"?"EDITA AI":profileMap[row.author_id]?.display_name||"Участник",
    username:profileMap[row.author_id]?.username||null
  }));
}

export async function GET(req:NextRequest,{params}:{params:Promise<{groupId:string}>}){
  const {groupId}=await params;
  const granted=await access(req,groupId);
  if(!granted)return NextResponse.json({error:"Чат доступен только участникам группы."},{status:403});
  try{
    return NextResponse.json({messages:await messages(granted.service,groupId)});
  }catch{
    return NextResponse.json({error:"Не удалось загрузить чат."},{status:503});
  }
}

export async function POST(req:NextRequest,{params}:{params:Promise<{groupId:string}>}){
  const {groupId}=await params;
  const granted=await access(req,groupId);
  if(!granted)return NextResponse.json({error:"Чат доступен только участникам группы."},{status:403});

  const body=await req.json().catch(()=>({}));
  const content=String(body?.content||"").trim();
  if(!content)return NextResponse.json({error:"Напиши сообщение."},{status:400});
  if(content.length>1400)return NextResponse.json({error:"Сообщение должно быть короче 1400 символов."},{status:400});

  const {data:last}=await granted.service.from("group_messages")
    .select("created_at")
    .eq("group_id",groupId)
    .eq("author_id",granted.user.id)
    .order("created_at",{ascending:false})
    .limit(1)
    .maybeSingle();
  if(last&&Date.now()-new Date(last.created_at).getTime()<1200){
    return NextResponse.json({error:"Слишком быстро. Подожди секунду и отправь снова."},{status:429});
  }

  const moderation=await moderateGroupMessage(content);
  if(!moderation.allowed){
    await granted.service.from("group_messages").insert({
      group_id:groupId,
      author_id:granted.user.id,
      sender_kind:"user",
      content:"Сообщение скрыто модерацией.",
      status:"removed",
      moderation_reason:moderation.reason||"policy"
    });
    return NextResponse.json({error:moderation.message||"Сообщение не прошло модерацию."},{status:422});
  }

  const {error:insertError}=await granted.service.from("group_messages").insert({
    group_id:groupId,
    author_id:granted.user.id,
    sender_kind:"user",
    content,
    status:"published"
  });
  if(insertError)return NextResponse.json({error:"Не удалось отправить сообщение."},{status:503});

  const asksAi=/^\s*\/ai\b/i.test(content)||/@edita\b/i.test(content)||content.includes("?");
  if(asksAi){
    const {data:recent}=await granted.service.from("group_messages")
      .select("sender_kind,content")
      .eq("group_id",groupId)
      .eq("status","published")
      .order("created_at",{ascending:false})
      .limit(8);
    const context=(recent||[]).reverse().map((item:any)=>(item.sender_kind==="ai"?"EDITA AI: ":"Участник: ")+item.content);
    const cleanQuestion=content.replace(/^\s*\/ai\s*/i,"").replace(/@edita\b/ig,"").trim();
    const reply=await createGroupAiReply(cleanQuestion||content,context);
    await granted.service.from("group_messages").insert({
      group_id:groupId,
      author_id:null,
      sender_kind:"ai",
      content:reply.slice(0,3000),
      status:"published"
    });
  }

  return NextResponse.json({ok:true,messages:await messages(granted.service,groupId)});
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){
  const h=req.headers.get("authorization");
  return h?.startsWith("Bearer ")?h.slice(7):null;
}

async function auth(req:NextRequest){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  return user&&service?{user,service}:null;
}

function scope(profile:any){
  return profile?.onboarding?.ageGroup||"18+";
}

export async function GET(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});

  const {data:memberships}=await a.service.from("study_group_members")
    .select("group_id,member_role")
    .eq("user_id",a.user.id);
  const ids=(memberships||[]).map((m:any)=>m.group_id);
  if(!ids.length)return NextResponse.json({groups:[]});

  const {data:groups}=await a.service.from("study_groups")
    .select("id,name,description,owner_id,age_scope,join_code,max_members,created_at")
    .in("id",ids);

  const result=await Promise.all((groups||[]).map(async(g:any)=>{
    const {data:members}=await a.service.from("study_group_members")
      .select("user_id,member_role,joined_at")
      .eq("group_id",g.id);

    const userIds=(members||[]).map((m:any)=>m.user_id);
    const {data:profiles}=userIds.length
      ? await a.service.from("public_profiles")
          .select("id,username,display_name,level,xp,rating_points")
          .in("id",userIds)
      : {data:[] as any[]};

    const pmap=Object.fromEntries((profiles||[]).map((p:any)=>[p.id,p]));
    return {
      ...g,
      members:(members||[])
        .map((m:any)=>({...m,profile:pmap[m.user_id]||null}))
        .sort((x:any,y:any)=>(y.profile?.rating_points||0)-(x.profile?.rating_points||0))
    };
  }));

  return NextResponse.json({groups:result});
}

export async function POST(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});

  const body=await req.json().catch(()=>({}));
  const action=String(body?.action||"");
  const {data:profile}=await a.service.from("profiles")
    .select("onboarding")
    .eq("id",a.user.id)
    .maybeSingle();
  const myScope=scope(profile);

  if(action==="create"){
    const name=String(body?.name||"").trim().slice(0,80);
    const description=String(body?.description||"").trim().slice(0,300);
    if(name.length<2)return NextResponse.json({error:"Название группы слишком короткое."},{status:400});

    const {data,error}=await a.service.from("study_groups").insert({
      owner_id:a.user.id,
      name,
      description,
      age_scope:myScope
    }).select("id,name,description,join_code,age_scope,max_members").single();

    if(error)return NextResponse.json({error:error.message},{status:400});
    return NextResponse.json({ok:true,group:data});
  }

  if(action==="join"){
    const code=String(body?.code||"").trim().toUpperCase();
    const {data:group}=await a.service.from("study_groups")
      .select("id,name,age_scope,max_members")
      .eq("join_code",code)
      .maybeSingle();

    if(!group)return NextResponse.json({error:"Группа с таким кодом не найдена."},{status:404});
    if(group.age_scope!==myScope){
      return NextResponse.json({error:"Эта группа относится к другой возрастной категории."},{status:403});
    }

    const {count}=await a.service.from("study_group_members")
      .select("user_id",{count:"exact",head:true})
      .eq("group_id",group.id);

    if((count||0)>=(group.max_members||10)){
      return NextResponse.json({error:"В группе уже нет свободных мест."},{status:409});
    }

    const {error}=await a.service.from("study_group_members").upsert({
      group_id:group.id,
      user_id:a.user.id,
      member_role:"member"
    },{onConflict:"group_id,user_id"});

    if(error)return NextResponse.json({error:error.message},{status:400});
    return NextResponse.json({ok:true,group});
  }

  return NextResponse.json({error:"Неизвестное действие."},{status:400});
}

