import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@supabase/supabase-js";
import { getSupabaseServiceClient } from "@/lib/server-supabase";

type PortfolioItem={id:string;title:string;video_url:string;display_url?:string;tags:string[];ai_score:number|null};

export default async function PublicPortfolio({params}:{params:Promise<{username:string}>}) {
  const {username}=await params;
  const url=process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key=process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;

  let profile:any=null;
  let items:PortfolioItem[]=[];

  if(url&&key){
    const supabase=createClient(url,key,{auth:{persistSession:false}});
    const {data}=await supabase.from("public_profiles")
      .select("id,display_name,username,level,ai_score,skills")
      .eq("username",username).maybeSingle();
    profile=data;
    if(profile){
      const {data:portfolio}=await supabase.from("portfolio_items")
        .select("id,title,video_url,tags,ai_score")
        .eq("editor_id",profile.id)
        .order("created_at",{ascending:false});
      items=(portfolio||[]) as PortfolioItem[];
      const service=getSupabaseServiceClient();
      if(service){
        items=await Promise.all(items.map(async item=>{
          if(/^https?:\/\//.test(item.video_url))return {...item,display_url:item.video_url};
          const {data:signed}=await service.storage.from("challenge-submissions").createSignedUrl(item.video_url,60*15);
          return {...item,display_url:signed?.signedUrl||""};
        }));
      }else{
        items=items.map(item=>({...item,display_url:/^https?:\/\//.test(item.video_url)?item.video_url:""}));
      }
    }
  }

  if(!profile&&username==="demo"){
    profile={display_name:"EDITA Demo Editor",username:"demo",level:5,ai_score:82,skills:["Short-form","CapCut","Talking Head"]};
    items=[
      {id:"1",title:"VOLT / Gym Promo",video_url:"",tags:["ads","reels"],ai_score:91},
      {id:"2",title:"Finance Expert Reel",video_url:"",tags:["talking-head"],ai_score:86},
      {id:"3",title:"North Coffee Challenge",video_url:"",tags:["winner","commercial"],ai_score:90},
    ];
  }

  if(!profile) notFound();

  return <main className="public-portfolio">
    <div className="portfolio-shell">
      <nav className="pricing-nav"><Link href="/" className="brand">EDITA<span>.</span></Link><Link href="/signup">Создать свой профиль</Link></nav>
      <div className="portfolio-hero">
        <div><div className="eyebrow">VERIFIED EDITOR</div><h1>{profile.display_name}</h1><p>@{profile.username}</p></div>
        <div className="portfolio-score"><strong>{profile.ai_score||"—"}</strong><span>AI Skill Score</span></div>
      </div>
      <div className="portfolio-tags">{(profile.skills||[]).map((s:string)=><span className="tag" key={s}>{s}</span>)}</div>
      <section className="portfolio-work-grid">
        {items.length?items.map(item=><article className="portfolio-work" key={item.id}>
          <div className="work-preview">{item.display_url&&isDirectVideo(item.display_url)?<video controls preload="metadata" src={item.display_url}/>:<span>EDITA WORK</span>}</div>
          <h2>{item.title}</h2>
          <div className="work-meta"><span>{(item.tags||[]).join(" · ")}</span>{item.ai_score!=null&&<b>AI {item.ai_score}</b>}</div>{item.display_url&&!isDirectVideo(item.display_url)&&<a className="work-link" href={item.display_url} target="_blank" rel="noreferrer">Открыть работу ↗</a>}
        </article>):<div className="legal-card"><p>Портфолио пока пустое.</p></div>}
      </section>
    </div>
  </main>
}

function isDirectVideo(url:string){return /\\.(mp4|webm|mov)(\\?|$)/i.test(url)||url.includes("supabase")}

"use client";

import {FormEvent,useEffect,useMemo,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import type {AiChatMessage} from "@/lib/ai-history";

type CoachContext={
  level?:string;
  editor?:string;
  goal?:string;
  role?:string|null;
  xp?:number;
  completedLessons?:string[];
  lessonSlug?:string;
  lessonTitle?:string;
  lessonSummary?:string;
  lessonSteps?:string[];
};

type AiCoachProps={
  scopeKey:string;
  title?:string;
  welcome?:string;
  prompts?:string[];
  context?:CoachContext;
  compact?:boolean;
};

const defaultWelcome="Привет! Спроси обычными словами. Я объясню коротко, покажу шаги и скажу, как проверить результат.";

export default function AiCoach({scopeKey,title="AI Помощник",welcome=defaultWelcome,prompts=[],context={},compact=false}:AiCoachProps){
  const localKey=useMemo(()=>"edita_ai_chat_v1:"+scopeKey,[scopeKey]);
  const [messages,setMessages]=useState<AiChatMessage[]>([{from:"ai",text:welcome}]);
  const [input,setInput]=useState("");
  const [loading,setLoading]=useState(false);
  const [historyLoading,setHistoryLoading]=useState(true);
  const [storageMode,setStorageMode]=useState<"account"|"browser">("browser");
  const [notice,setNotice]=useState("");

  useEffect(()=>{
    let active=true;
    async function load(){
      try{
        const supabase=getSupabaseBrowserClient();
        const {data:{session}}=await supabase.auth.getSession();
        if(session?.access_token){
          const params=new URLSearchParams({scope:scopeKey,title});
          const response=await fetch("/api/ai/history?"+params,{headers:{Authorization:"Bearer "+session.access_token},cache:"no-store"});
          if(response.ok){
            const data=await response.json();
            if(active){
              setStorageMode("account");
              setMessages(data.messages?.length?data.messages:[{from:"ai",text:welcome}]);
            }
            return;
          }
        }
        const raw=localStorage.getItem(localKey);
        const saved=raw?JSON.parse(raw):null;
        if(active&&Array.isArray(saved)&&saved.length)setMessages(saved.slice(-80));
      }catch{}
      finally{if(active)setHistoryLoading(false)}
    }
    void load();
    return()=>{active=false};
  },[localKey,scopeKey,title,welcome]);

  useEffect(()=>{
    if(historyLoading||storageMode!=="browser")return;
    try{localStorage.setItem(localKey,JSON.stringify(messages.slice(-80)))}catch{}
  },[historyLoading,localKey,messages,storageMode]);

  async function send(text:string){
    const question=text.trim();
    if(!question||loading)return;
    const next=[...messages,{from:"user" as const,text:question}];
    setMessages(next);setInput("");setLoading(true);setNotice("");
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;
      const response=await fetch("/api/ai",{
        method:"POST",
        headers,
        body:JSON.stringify({
          message:question,
          context:{...context,scopeKey},
          history:messages.slice(-12)
        })
      });
      const data=await response.json();
      const reply=data.reply||"Не получилось ответить. Попробуй ещё раз чуть позже.";
      setMessages(current=>[...current,{from:"ai",text:reply}]);
      if(data.saved)setStorageMode("account");
    }catch{
      setMessages(current=>[...current,{from:"ai",text:"Связь прервалась. Вопрос не потерян — нажми «Спросить» ещё раз, когда интернет восстановится."}]);
    }finally{setLoading(false)}
  }

  async function submit(event:FormEvent){event.preventDefault();await send(input)}

  async function clear(){
    setNotice("");
    try{
      if(storageMode==="account"){
        const supabase=getSupabaseBrowserClient();
        const {data:{session}}=await supabase.auth.getSession();
        if(session?.access_token){
          await fetch("/api/ai/history?scope="+encodeURIComponent(scopeKey),{method:"DELETE",headers:{Authorization:"Bearer "+session.access_token}});
        }
      }else localStorage.removeItem(localKey);
      setMessages([{from:"ai",text:welcome}]);
      setNotice("История очищена.");
    }catch{setNotice("Не удалось очистить историю.")}
  }

  return <section className={"ai-coach "+(compact?"compact":"")} aria-label={title}>
    <div className="ai-coach-head">
      <div><span className="ai-orb" aria-hidden="true">AI</span><div><b>{title}</b><small>{storageMode==="account"?"Диалог сохраняется в аккаунте":"Диалог сохраняется в этом браузере"}</small></div></div>
      <button type="button" className="ai-clear" onClick={clear}>Очистить</button>
    </div>
    <div className="ai-feed" aria-live="polite">
      {historyLoading?<div className="ai-thinking">Загружаю диалог…</div>:messages.map((message,index)=><article className={"ai-message "+message.from} key={message.id||index}>
        <span>{message.from==="ai"?"EDITA AI":"Ты"}</span>
        <AiMessageText text={message.text}/>
      </article>)}
      {loading?<div className="ai-thinking">Разбираю вопрос и готовлю шаги…</div>:null}
    </div>
    {prompts.length?<div className="ai-prompts">{prompts.slice(0,4).map(prompt=><button type="button" key={prompt} onClick={()=>void send(prompt)} disabled={loading}>{prompt}</button>)}</div>:null}
    <form className="ai-form" onSubmit={submit}>
      <textarea value={input} onChange={event=>setInput(event.target.value)} maxLength={4000} rows={compact?2:3} placeholder="Например: я не вижу кнопку «Разделить». Что нажать?"/>
      <button className="btn btn-lime" disabled={loading||!input.trim()}>{loading?"Думаю…":"Спросить AI"}</button>
    </form>
    {notice?<div className="ai-notice">{notice}</div>:null}
    <small className="ai-disclaimer">Кнопки в приложениях иногда переезжают после обновлений. AI уточнит устройство и версию, если это важно.</small>
  </section>
}

function AiMessageText({text}:{text:string}){
  const lines=text.replace(/\r/g,"").split("\n").filter((line,index,all)=>line.trim()||all[index-1]?.trim());
  return <div className="ai-message-text">{lines.map((raw,index)=>{
    const line=raw.trim().replace(/^#{1,4}\s*/,"").replace(/^\*\*(.*?)\*\*:?$/,"$1");
    if(!line)return <span className="ai-space" key={index}/>;
    if(/^\d+[.)]\s/.test(line))return <div className="ai-numbered" key={index}><b>{line.match(/^\d+/)?.[0]}</b><p>{line.replace(/^\d+[.)]\s*/,"")}</p></div>;
    if(/^[-•]\s/.test(line))return <div className="ai-bullet" key={index}><b>•</b><p>{line.replace(/^[-•]\s*/,"")}</p></div>;
    if(/^(Что это|Что сделать|Как проверить|Лайфхак|Куда нажать|Следующий шаг)[:：]?$/.test(line))return <h4 key={index}>{line.replace(/[:：]$/,"")}</h4>;
    return <p key={index}>{line.replace(/\*\*/g,"")}</p>;
  })}</div>
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type BrandContext={
  audience:string;
  tone:string;
  colors:string;
  references:string;
  editingRules:string;
};

const empty:BrandContext={audience:"",tone:"",colors:"",references:"",editingRules:""};

export default function BrandBrain({viewerName="Business"}:{viewerName?:string}){
  const [form,setForm]=useState<BrandContext>(empty);
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [message,setMessage]=useState("");

  useEffect(()=>{void load()},[]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){
      try{
        const raw=localStorage.getItem("edita_brand_brain");
        if(raw)setForm(JSON.parse(raw));
      }catch{}
      return;
    }
    const {data:{user}}=await supabase.auth.getUser();
    if(!user)return;
    let {data}=await supabase.from("businesses").select("id,brand_context").eq("owner_id",user.id).maybeSingle();
    if(!data){
      const {data:created}=await supabase.from("businesses")
        .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
        .select("id,brand_context")
        .single();
      data=created;
    }
    if(data){
      setBusinessId(data.id);
      setForm({...empty,...(data.brand_context||{})});
    }
  }

  async function save(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase||!businessId){
      localStorage.setItem("edita_brand_brain",JSON.stringify(form));
      setMessage("Профиль бренда сохранён локально в demo.");
      return;
    }
    const {error}=await supabase.from("businesses").update({brand_context:form}).eq("id",businessId);
    setMessage(error?error.message:"Профиль бренда сохранён. Его можно использовать для новых ТЗ и AI-проверок.");
  }

  return <section className="card brand-brain">
    <div className="eyebrow">ПРОФИЛЬ БРЕНДА</div>
    <h3>Контекст бренда для всех монтажёров</h3>
    <p className="muted">Сохраняем стиль один раз, чтобы новый редактор не начинал с нуля.</p>
    <form className="business-form" onSubmit={save}>
      <input placeholder="Целевая аудитория" value={form.audience} onChange={e=>setForm({...form,audience:e.target.value})}/>
      <input placeholder="Tone of voice: премиальный, дерзкий, спокойный…" value={form.tone} onChange={e=>setForm({...form,tone:e.target.value})}/>
      <input placeholder="Цвета / шрифты / визуальные правила" value={form.colors} onChange={e=>setForm({...form,colors:e.target.value})}/>
      <input placeholder="Ссылки на лучшие референсы" value={form.references} onChange={e=>setForm({...form,references:e.target.value})}/>
      <textarea placeholder="Повторяющиеся пожелания по монтажу и правкам" value={form.editingRules} onChange={e=>setForm({...form,editingRules:e.target.value})}/>
