"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Verification={
  business?:{
    id:string;
    name:string;
    verified:boolean;
    verification_status:string;
    verification_level:string;
    verification_note?:string|null;
  };
  request?:{
    id:string;
    requested_level:string;
    status:string;
    review_note?:string|null;
    created_at:string;
  }|null;
};

export default function BusinessVerification(){
  const [data,setData]=useState<Verification|null>(null);
  const [files,setFiles]=useState<File[]>([]);
  const [loading,setLoading]=useState(false);
  const [message,setMessage]=useState("");
  const [form,setForm]=useState({
    requestedLevel:"verified_company",
    legalName:"",
    inn:"",
    registrationNumber:"",
    websiteUrl:"",
    socialUrl:"",
    reportedAudience:""
  });

  useEffect(()=>{
    try{
      const raw=localStorage.getItem("edita_business_verification_prefill");
      if(raw){
        const saved=JSON.parse(raw);
        setForm(v=>({...v,...saved}));
      }
    }catch{}
    void load();
  },[]);

  async function authHeaders():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    try{
      const headers=await authHeaders();
      const r=await fetch("/api/business/verification",{headers,cache:"no-store"});
      const json=await r.json();
      if(r.ok)setData(json);
    }catch{}
  }

  async function submit(e:FormEvent){
    e.preventDefault();
    setMessage("");
    if(files.length===0){setMessage("Добавь документ: PDF, JPG или PNG.");return;}
    if(files.length>3){setMessage("Можно добавить не больше 3 файлов.");return;}
    if(files.some(f=>f.size>15*1024*1024)){setMessage("Один файл не должен быть больше 15 МБ.");return;}

    setLoading(true);
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{user}}=await supabase.auth.getUser();
      const {data:{session}}=await supabase.auth.getSession();
      if(!user||!session?.access_token)throw new Error("Сначала войди в бизнес-аккаунт.");

      const paths:string[]=[];
      for(const file of files){
        const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"_");
        const path=user.id+"/"+Date.now()+"-"+Math.random().toString(36).slice(2,8)+"-"+safe;
        const up=await supabase.storage.from("business-verification")
          .upload(path,file,{upsert:false,contentType:file.type||"application/octet-stream"});
        if(up.error)throw new Error("Не удалось загрузить документ: "+up.error.message);
        paths.push(path);
      }

      const r=await fetch("/api/business/verification",{
        method:"POST",
        headers:{"Content-Type":"application/json",Authorization:"Bearer "+session.access_token},
        body:JSON.stringify({
          ...form,
          reportedAudience:form.reportedAudience?Number(form.reportedAudience):null,
          documentPaths:paths
        })
      });
      const json=await r.json();
      if(!r.ok)throw new Error(json?.error||"Не удалось отправить заявку.");

      setFiles([]);
      localStorage.removeItem("edita_business_verification_prefill");
      setMessage("Заявка отправлена. Проверка проходит вручную: документы и публичные ссылки сверяются человеком.");
      await load();
    }catch(e){
      setMessage(e instanceof Error?e.message:"Не удалось отправить заявку.");
    }finally{setLoading(false)}
  }

  const business=data?.business;
  const request=data?.request;
  const status=business?.verified
    ? badgeName(business.verification_level)
    : request?.status==="pending"||business?.verification_status==="pending"
      ?"На проверке"
      :"Не проверен";

  return <section className="card verification-card">
    <div className="verification-head">
      <div>
        <div className="eyebrow">ПРОВЕРКА БИЗНЕСА</div>
        <h3>Подтверди, кто стоит за заданиями</h3>
      </div>
      <span className={"verification-badge "+(business?.verified?"ok":request?.status==="pending"?"pending":"")}>{status}</span>
    </div>

    <p className="muted">Проверенный бизнес вызывает больше доверия. Для платных Challenge и вакансий EDITA требует проверку компании.</p>

    {business?.verified?<div className="verification-success">
      <b>Готово: {badgeName(business.verification_level)}</b>
      <span>Монтажёры будут видеть отметку рядом с названием компании.</span>
    </div>:request?.status==="pending"?<div className="auth-msg">
      Заявка уже отправлена и ждёт ручной проверки. Мы не выдаём отметку только по числу подписчиков: публичные страницы и документы сверяются отдельно.
    </div>:<form className="business-form" onSubmit={submit}>
      <label className="field-label">Какую отметку хочешь получить?</label>
      <select value={form.requestedLevel} onChange={e=>setForm({...form,requestedLevel:e.target.value})}>
        <option value="verified_company">Проверенная компания — по документам</option>
        <option value="popular_brand">Известный бренд — документы + публичные страницы</option>
      </select>

      <input required placeholder="Официальное название компании или ИП" value={form.legalName} onChange={e=>setForm({...form,legalName:e.target.value})}/>
      <div className="split-fields">
        <input inputMode="numeric" placeholder="ИНН: 10 или 12 цифр" value={form.inn} onChange={e=>setForm({...form,inn:e.target.value})}/>
        <input inputMode="numeric" placeholder="ОГРН / ОГРНИП" value={form.registrationNumber} onChange={e=>setForm({...form,registrationNumber:e.target.value})}/>
      </div>
      <input type="url" placeholder="Сайт компании (если есть)" value={form.websiteUrl} onChange={e=>setForm({...form,websiteUrl:e.target.value})}/>
      <input type="url" placeholder="Ссылка на публичную соцсеть бренда" value={form.socialUrl} onChange={e=>setForm({...form,socialUrl:e.target.value})}/>
      <input min="0" type="number" placeholder="Примерный размер аудитории (необязательно)" value={form.reportedAudience} onChange={e=>setForm({...form,reportedAudience:e.target.value})}/>

      <label className="verification-upload">
        <b>Документы</b>
        <span>PDF, JPG или PNG. До 3 файлов, каждый до 15 МБ. Файлы закрыты от других пользователей.</span>
        <input type="file" accept=".pdf,image/jpeg,image/png" multiple onChange={e=>setFiles(Array.from(e.target.files||[]).slice(0,3))}/>
      </label>
      {files.length>0&&<div className="muted">{files.map(f=>f.name).join(" · ")}</div>}

      <button className="btn btn-dark" disabled={loading}>{loading?"Отправляем…":"Отправить на проверку"}</button>
    </form>}

    {request?.status==="rejected"&&<div className="auth-msg">Нужно исправить заявку: {request.review_note||"проверь документы и ссылки и отправь новую заявку."}</div>}
    {message&&<div className="auth-msg">{message}</div>}
    <p className="muted">Отметка «Известный бренд» не выдаётся автоматически по введённому числу подписчиков. EDITA проверяет открытые страницы и документы вручную.</p>
  </section>
}

function badgeName(level?:string){
  if(level==="popular_brand")return "Известный бренд";
  if(level==="partner")return "Партнёр EDITA";
  if(level==="verified_company")return "Проверенная компания";
  return "Проверенный бизнес";
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type League={id:string;name:string;verification_level:string;score:number;campaigns:number;applications:number};
type EditorCampaign={id:string;title:string;goal:string;content_types:string[];budget_text:string;creator_slots:number;requirements:string;ends_at?:string|null;myStatus?:string|null;business?:{name:string;verification_level:string}};
type BusinessApplication={id:string;editor_id:string;portfolio_url?:string|null;note?:string|null;status:string;editor?:{display_name?:string;username?:string}|null};
type BusinessCampaign=EditorCampaign&{applications:BusinessApplication[]};

export default function CampaignHub({mode}:{mode:"editor"|"business"}){
  const [campaigns,setCampaigns]=useState<(EditorCampaign|BusinessCampaign)[]>([]);
  const [league,setLeague]=useState<League[]>([]);
  const [business,setBusiness]=useState<any>(null);
  const [message,setMessage]=useState("");
  const [busy,setBusy]=useState(false);
  const [apply,setApply]=useState<Record<string,{portfolioUrl:string;note:string}>>({});
  const [form,setForm]=useState({
    title:"",
    goal:"",
    budgetText:"",
    creatorSlots:"3",
    requirements:"",
    contentTypes:"Reels, UGC"
  });

  useEffect(()=>{void load()},[]);

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function call(body?:any){
    const h=await headers();
    const r=await fetch("/api/campaigns",{
      method:body?"POST":"GET",
      headers:body?{...h,"Content-Type":"application/json"}:h,
      body:body?JSON.stringify(body):undefined,
      cache:"no-store"
    });
    const data=await r.json();
    if(!r.ok)throw new Error(data?.error||"Не удалось выполнить действие.");
    return data;
  }

  async function load(){
    try{
      const d=await call();
      setCampaigns(d.campaigns||[]);
      setLeague(d.league||[]);
      setBusiness(d.business||null);
    }catch(e){setMessage(e instanceof Error?e.message:"Не удалось загрузить кампании.")}
  }

  async function create(e:FormEvent){
    e.preventDefault();setBusy(true);setMessage("");
    try{
      await call({
        action:"create",
        title:form.title,
        goal:form.goal,
        budgetText:form.budgetText,
        creatorSlots:Number(form.creatorSlots)||1,
        requirements:form.requirements,
        contentTypes:form.contentTypes.split(",").map(v=>v.trim()).filter(Boolean)
      });
      setForm({title:"",goal:"",budgetText:"",creatorSlots:"3",requirements:"",contentTypes:"Reels, UGC"});
      setMessage("Кампания опубликована. Теперь монтажёры могут откликаться внутри EDITA.");
      await load();
    }catch(e){setMessage(e instanceof Error?e.message:"Ошибка.");}
    finally{setBusy(false)}
  }

  async function applyTo(id:string){
    setBusy(true);setMessage("");
    const item=apply[id]||{portfolioUrl:"",note:""};
    try{
      await call({action:"apply",campaignId:id,...item});
      setMessage("Отклик отправлен компании.");
      await load();
    }catch(e){setMessage(e instanceof Error?e.message:"Ошибка.");}
    finally{setBusy(false)}
  }

  async function setApplication(id:string,status:string){
    setBusy(true);setMessage("");
    try{
      await call({action:"application_status",applicationId:id,status});
      setMessage(status==="accepted"?"Креатор принят в кампанию.":"Статус обновлён.");
      await load();
    }catch(e){setMessage(e instanceof Error?e.message:"Ошибка.");}
    finally{setBusy(false)}
  }

  return <div className="campaign-hub">
    {message&&<div className="auth-msg">{message}</div>}

    {mode==="business"&&<section className="card">
      <div className="eyebrow">CAMPAIGN HUB</div>
      <h3>Запустить маркетинговую кампанию</h3>
      <p className="muted">Это не обычная вакансия. Здесь можно собрать несколько креаторов под запуск продукта, UGC, серию Reels или постоянный поток контента.</p>
      {!business?.verified&&<div className="auth-msg">Публиковать кампании может только проверенная компания. Сначала закончи проверку бизнеса выше.</div>}
      <form className="business-form" onSubmit={create}>
        <input required placeholder="Название кампании" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
        <textarea required placeholder="Цель: что должна дать эта кампания?" value={form.goal} onChange={e=>setForm({...form,goal:e.target.value})}/>
        <input required placeholder="Условия оплаты, например: 5 000 ₽ за принятый ролик" value={form.budgetText} onChange={e=>setForm({...form,budgetText:e.target.value})}/>
        <div className="split-fields">
          <input min="1" max="100" type="number" placeholder="Сколько креаторов" value={form.creatorSlots} onChange={e=>setForm({...form,creatorSlots:e.target.value})}/>
          <input placeholder="Форматы через запятую" value={form.contentTypes} onChange={e=>setForm({...form,contentTypes:e.target.value})}/>
        </div>
        <textarea placeholder="Что обязательно должно быть в роликах" value={form.requirements} onChange={e=>setForm({...form,requirements:e.target.value})}/>
        <button className="btn btn-dark" disabled={busy||!business?.verified}>{busy?"Публикуем…":business?.verified?"Опубликовать кампанию":"Сначала пройти проверку"}</button>
      </form>
    </section>}

    <section className="card">
      <div className="eyebrow">{mode==="business"?"МОИ КАМПАНИИ":"КАМПАНИИ ПРОВЕРЕННЫХ БРЕНДОВ"}</div>
      <h3>{mode==="business"?"Креаторы и отклики":"Можно откликнуться прямо из EDITA"}</h3>
      <div className="business-stack">
        {campaigns.length===0&&<p className="muted">Открытых кампаний пока нет.</p>}
        {campaigns.map((raw:any)=><article className="campaign-card" key={raw.id}>
          <div className="verification-head">
            <div>
              <div className="eyebrow">{mode==="editor"?(raw.business?.name||"Проверенный бизнес"):"КАМПАНИЯ"}</div>
              <h3>{raw.title}</h3>
            </div>
            {mode==="editor"&&<span className="verification-badge ok">✓ Проверенная компания</span>}
          </div>
          <p>{raw.goal}</p>
          <div className="chip-row">{(raw.content_types||[]).map((x:string)=><span className="tag" key={x}>{x}</span>)}</div>
          <div className="campaign-meta"><span><b>Оплата:</b> {raw.budget_text}</span><span><b>Нужно креаторов:</b> {raw.creator_slots}</span></div>
          {raw.requirements&&<div className="lesson-example"><b>Что важно</b><span>{raw.requirements}</span></div>}

          {mode==="editor"&&(raw.myStatus?<div className="auth-msg">Твой отклик: <b>{statusRu(raw.myStatus)}</b></div>:<div className="business-form campaign-apply">
            <input type="url" placeholder="Ссылка на портфолио" value={apply[raw.id]?.portfolioUrl||""} onChange={e=>setApply({...apply,[raw.id]:{...(apply[raw.id]||{portfolioUrl:"",note:""}),portfolioUrl:e.target.value}})}/>
            <textarea placeholder="Коротко: почему ты подходишь" value={apply[raw.id]?.note||""} onChange={e=>setApply({...apply,[raw.id]:{...(apply[raw.id]||{portfolioUrl:"",note:""}),note:e.target.value}})}/>
            <button className="btn btn-dark" disabled={busy} onClick={()=>applyTo(raw.id)}>Откликнуться</button>
          </div>)}

          {mode==="business"&&<div className="campaign-applications">
            <b>Отклики · {(raw.applications||[]).length}</b>
            {(raw.applications||[]).length===0?<p className="muted">Пока никто не откликнулся.</p>:(raw.applications||[]).map((a:BusinessApplication)=><div className="talent-row" key={a.id}>
              <div>
                <b>@{a.editor?.username||"editor"}</b>
                <span>{a.note||"Без комментария"}</span>
                {a.portfolio_url&&<a href={a.portfolio_url} target="_blank" rel="noreferrer">Портфолио ↗</a>}
              </div>
              <div className="chip-row">
                <button className="mini-btn" onClick={()=>setApplication(a.id,"shortlisted")}>В избранное</button>
                <button className="mini-btn" onClick={()=>setApplication(a.id,"accepted")}>Принять</button>
                <button className="mini-btn" onClick={()=>setApplication(a.id,"declined")}>Отказать</button>
              </div>
            </div>)}
          </div>}
        </article>)}
      </div>
    </section>

    <section className="card">
      <div className="eyebrow">BRAND LEAGUE · АКТИВНОСТЬ</div>
      <h3>Компании, которые реально работают с креаторами</h3>
      <p className="muted">Это рейтинг активности, а не обещание качества. Отдельный рейтинг качества строится по оценкам реальных участников.</p>
      <div className="business-league-list">
        {league.length===0?<p className="muted">Лига заполнится после первых кампаний.</p>:league.map((b,i)=><div className="business-league-row" key={b.id}><b>#{i+1}</b><span>{b.name}</span><strong>{b.score}</strong></div>)}
      </div>
    </section>
  </div>
}

function statusRu(status?:string){
  if(status==="shortlisted")return "в избранном";
  if(status==="accepted")return "принят";
  if(status==="declined")return "не выбран";
  return "отправлен";
}

"use client";

import {FormEvent,useEffect,useMemo,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import {extractVideoFrames} from "@/lib/video-frames";

type Role="editor"|"business"|null;
type Challenge={
  id:string;
  business_id?:string|null;
  brand:string;
  title:string;
  brief:string;
  prize_cents:number;
  ends_at:string|null;
  status:string;
  source_assets:string[];
  brand_verified?:boolean;
  verification_level?:string;
};
type Submission={
  id:string;
  challenge_id:string;
  editor_id:string;
  editor_name:string;
  storage_path:string;
  video_url:string;
  ai_score:number|null;
  status:string;
};

const demoChallenges:Challenge[]=[
  {id:"demo-coffee",brand:"ПРИМЕР · NORTH COFFEE",title:"Reel из утренней съёмки",brief:"Собери вертикальный Reel 20–30 секунд. Покажи атмосферу утра, продукт крупно и закончи понятным CTA. Музыка не должна перебивать естественный звук.",prize_cents:0,ends_at:new Date(Date.now()+3*86400000).toISOString(),status:"open",source_assets:[]},
  {id:"demo-fitness",brand:"ПРИМЕР · VOLT FITNESS",title:"Реклама нового зала",brief:"30 секунд. Быстрый hook, 3 ключевых преимущества, динамичный sound design. Избегай перегруза переходами.",prize_cents:0,ends_at:new Date(Date.now()+5*86400000).toISOString(),status:"open",source_assets:[]},
  {id:"demo-motion",brand:"ПРИМЕР · MOTION LAB",title:"Talking-head Short",brief:"Сделай экспертный Short до 35 секунд: чистая речь, крупные субтитры, B-roll только по смыслу.",prize_cents:0,ends_at:new Date(Date.now()+2*86400000).toISOString(),status:"open",source_assets:[]},
];

export default function ChallengeCenter({role,viewerName,ageGroup,guardianVerified,mode}:{role:Role;viewerName:string;ageGroup?:string;guardianVerified?:boolean;mode:"arena"|"business"}){
  const [challenges,setChallenges]=useState<Challenge[]>(demoChallenges);
  const [selectedId,setSelectedId]=useState(demoChallenges[0].id);
  const [submissions,setSubmissions]=useState<Submission[]>([]);
  const [file,setFile]=useState<File|null>(null);
  const [message,setMessage]=useState("");
  const [loading,setLoading]=useState(false);
  const [loadingBrief,setLoadingBrief]=useState(false);
  const [brandContext,setBrandContext]=useState<Record<string,string>>({});
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [businessVerified,setBusinessVerified]=useState(false);
  const [form,setForm]=useState({brand:"",title:"",brief:"",sourceUrl:"",prize:"10000",deadline:""});

  const selected=useMemo(()=>challenges.find(c=>c.id===selectedId)||challenges[0],[challenges,selectedId]);

  useEffect(()=>{void load()},[role]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase)return;
    const {data:{user}}=await supabase.auth.getUser();
    if(!user)return;

    let ownedBusinessId:string|null=null;
    if(role==="business"){
      const {data:business}=await supabase.from("businesses").select("id,name,brand_context,verified,verification_level").eq("owner_id",user.id).maybeSingle();
      if(business){
        ownedBusinessId=business.id;
        setBrandContext((business.brand_context||{}) as Record<string,string>);
        setBusinessVerified(Boolean(business.verified));
      }else{
        const {data:created}=await supabase.from("businesses")
          .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
          .select("id,brand_context,verified,verification_level")
          .single();
        ownedBusinessId=created?.id||null;
        if(created?.brand_context)setBrandContext((created.brand_context||{}) as Record<string,string>);
        setBusinessVerified(Boolean(created?.verified));
      }
      setBusinessId(ownedBusinessId);
    }

    const {data,error}=await supabase.from("challenges")
      .select("id,business_id,title,brief,prize_cents,ends_at,status,source_assets")
      .eq("status","open").order("created_at",{ascending:false});

    if(!error&&data?.length){
      const businessIds=[...new Set(data.map((row:any)=>row.business_id).filter(Boolean))];
      const {data:publicBusinesses}=businessIds.length
        ? await supabase.from("public_businesses").select("id,name,verified,verification_level").in("id",businessIds)
        : {data:[] as any[]};
      const businessMap=Object.fromEntries((publicBusinesses||[]).map((b:any)=>[b.id,b]));
      const mapped:Challenge[]=data.map((row:any)=>({
        id:row.id,
        business_id:row.business_id,
        brand:businessMap[row.business_id]?.name||"EDITA BUSINESS",
        brand_verified:Boolean(businessMap[row.business_id]?.verified),
        verification_level:businessMap[row.business_id]?.verification_level||"basic",
        title:row.title,
        brief:row.brief,
        prize_cents:Number(row.prize_cents||0),
        ends_at:row.ends_at,
        status:row.status,
        source_assets:Array.isArray(row.source_assets)?row.source_assets.filter((v:any)=>typeof v==="string"):[],
      }));
      setChallenges(mapped);
      setSelectedId(mapped[0].id);
    } else if(!error) {
      setChallenges([]);
      setSelectedId("");
    }

    if(mode==="business"&&ownedBusinessId)await loadBusinessSubmissions(ownedBusinessId);
  }

  async function loadBusinessSubmissions(ownedBusinessId:string){
    const supabase=getSupabaseBrowserClient();
    if(!supabase)return;
    const {data:owned}=await supabase.from("challenges").select("id").eq("business_id",ownedBusinessId);
    const ids=(owned||[]).map((c:any)=>c.id);
    if(!ids.length){setSubmissions([]);return;}

    const {data}=await supabase.from("challenge_submissions")
      .select("id,challenge_id,video_url,ai_score,status,editor_id")
      .in("challenge_id",ids).order("created_at",{ascending:false});
    const rows=data||[];
    const editorIds=[...new Set(rows.map((r:any)=>r.editor_id))];
    let names:Record<string,string>={};

    if(editorIds.length){
      const {data:profiles}=await supabase.from("public_profiles").select("id,display_name").in("id",editorIds);
      names=Object.fromEntries((profiles||[]).map((p:any)=>[p.id,p.display_name||"Editor"]));
    }

    const mapped=await Promise.all(rows.map(async(r:any)=>{
      const {data:signed}=await supabase.storage.from("challenge-submissions").createSignedUrl(r.video_url,60*60);
      return {
        id:r.id,
        challenge_id:r.challenge_id,
        editor_id:r.editor_id,
        storage_path:r.video_url,
        video_url:signed?.signedUrl||"",
        ai_score:r.ai_score,
        status:r.status,
        editor_name:names[r.editor_id]||"Editor"
      } as Submission;
    }));
    setSubmissions(mapped);
  }

  async function submitWork(e:FormEvent){
    e.preventDefault();
    if(!selected||!file){setMessage("Сначала выбери видеофайл.");return;}
    if(role==="editor"&&ageGroup&&ageGroup!=="18+"&&!guardianVerified){
      setMessage("Коммерческие задания для пользователей младше 18 лет доступны только после подтверждения законного представителя. Обучение, Practice и AI доступны без этой отправки.");
      return;
    }

    setLoading(true);
    setMessage("Готовлю работу к отправке…");
    const currentFile=file;
    const supabase=getSupabaseBrowserClient();

    if(!supabase){
      try{
        setMessage("Видео принято в demo. AI анализирует ключевые кадры…");
        const review=await runAutoReview(currentFile,selected.brief,selected.id);
        setMessage("Демо-отправка завершена. AI Score: "+review.overall_score+"/100.");
      }catch{
        setMessage("Демо: работа принята, но AI-разбор не завершился.");
      }finally{
        setFile(null);setLoading(false);
      }
      return;
    }

    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setMessage("Войди в аккаунт монтажёра, чтобы отправить работу.");setLoading(false);return;}

    const safe=currentFile.name.replace(/[^a-zA-Z0-9._-]/g,"_");
    const path=user.id+"/"+selected.id+"/"+Date.now()+"-"+safe;

    setMessage("Загружаю видео в защищённое хранилище…");
    const upload=await supabase.storage.from("challenge-submissions")
      .upload(path,currentFile,{upsert:false,contentType:currentFile.type||"video/mp4"});
    if(upload.error){setMessage("Не удалось загрузить видео: "+upload.error.message);setLoading(false);return;}

    const {data:submission,error:insertError}=await supabase.from("challenge_submissions")
      .upsert({challenge_id:selected.id,editor_id:user.id,video_url:path,status:"submitted"},{onConflict:"challenge_id,editor_id"})
      .select("id").single();

    if(insertError||!submission){
      setMessage("Видео загружено, но submission не сохранился: "+(insertError?.message||"unknown error"));
      setLoading(false);return;
    }

    try{
      setMessage("Работа отправлена. EDITA AI делает первичный разбор…");
      const review=await runAutoReview(currentFile,selected.brief,selected.id);
      const {error:reviewError}=await supabase.from("challenge_submissions")
        .update({ai_score:review.overall_score,ai_feedback:review}).eq("id",submission.id);
      setMessage(reviewError
        ?"Работа отправлена. AI Score "+review.overall_score+"/100, но feedback не сохранился: "+reviewError.message
        :"Готово. Работа отправлена, AI Score: "+review.overall_score+"/100. Бизнес уже увидит оценку.");
    }catch{
      setMessage("Работа отправлена. AI Review не завершился — submission всё равно сохранён.");
    }

    setFile(null);setLoading(false);
  }

  async function runAutoReview(videoFile:File,brief:string,challengeId:string){
    const extracted=await extractVideoFrames(videoFile,6);
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    const token=session?.access_token;
    if(!token)throw new Error("Нужна авторизация.");
    const response=await fetch("/api/ai/video-review",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({frames:extracted.frames,duration:extracted.duration,width:extracted.width,height:extracted.height,brief,filename:videoFile.name,purpose:"arena",challengeId})});
    const data=await response.json();
    if(!response.ok||!data.review)throw new Error(data?.error||"AI review failed");
    return data.review;
  }

  async function improveBrief(){
    if(!form.brief.trim()){setMessage("Сначала набросай хотя бы несколько строк ТЗ.");return;}
    setLoadingBrief(true);setMessage("");
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;
      const r=await fetch("/api/ai/brief",{method:"POST",headers,body:JSON.stringify({brief:form.brief,brandContext})});
      const data=await r.json();
      if(!r.ok||!data.result)throw new Error(data?.error||"AI brief failed");
      const b=data.result;
      const formatted=[
        "Цель: "+b.goal,
        "Длительность: "+b.duration,
        "Формат: "+b.format,
        "",
        "Обязательно:",
        ...b.must_haves.map((v:string)=>"• "+v),
        "",
        "Избегать:",
        ...b.avoid.map((v:string)=>"• "+v),
        "",
        "Критерии приёмки:",
        ...b.checklist.map((v:string)=>"• "+v)
      ].join("\n");
      setForm(current=>({...current,title:current.title||b.title,brief:formatted}));
      setMessage("AI превратил черновик в проверяемое ТЗ. Проверь детали перед публикацией.");
    }catch(e){
      setMessage(e instanceof Error?e.message:"Не удалось улучшить ТЗ.");
    }finally{setLoadingBrief(false)}
  }

  async function createChallenge(e:FormEvent){
    e.preventDefault();
    if(!businessVerified){
      setMessage("Сначала пройди проверку компании выше. Непроверенный бизнес не может публиковать реальные Challenge.");
      return;
    }
    setLoading(true);setMessage("");
    const sourceAssets=form.sourceUrl.trim()?[form.sourceUrl.trim()]:[];
    const supabase=getSupabaseBrowserClient();

    if(!supabase||!businessId){
      const demo:Challenge={id:"local-"+Date.now(),business_id:"demo",brand:form.brand||viewerName,title:form.title,brief:form.brief,prize_cents:Number(form.prize||0)*100,ends_at:form.deadline?new Date(form.deadline).toISOString():null,status:"open",source_assets:sourceAssets};
      setChallenges(c=>[demo,...c]);setSelectedId(demo.id);setMessage("Пример задания создан только в браузере.");
      setLoading(false);return;
    }

    if(form.brand)await supabase.from("businesses").update({name:form.brand}).eq("id",businessId);

    const {data,error}=await supabase.from("challenges").insert({
      business_id:businessId,title:form.title,brief:form.brief,status:"open",
      prize_cents:Number(form.prize||0)*100,
      ends_at:form.deadline?new Date(form.deadline).toISOString():null,
      source_assets:sourceAssets
    }).select("id,business_id,title,brief,prize_cents,ends_at,status,source_assets").single();

    if(error){setMessage(error.message);setLoading(false);return;}
    const item:Challenge={...(data as any),brand:form.brand||viewerName,source_assets:(data as any).source_assets||[]};
    setChallenges(c=>[item,...c]);setSelectedId(item.id);setMessage("Задание опубликовано в Arena.");
    setForm({brand:form.brand,title:"",brief:"",sourceUrl:"",prize:"10000",deadline:""});setLoading(false);
  }

  async function setSubmissionStatus(id:string,status:"shortlisted"|"winner"){
    const supabase=getSupabaseBrowserClient();
    if(supabase){
      const {error}=await supabase.from("challenge_submissions").update({status}).eq("id",id);
      if(error){setMessage(error.message);return;}

      if(status==="winner"){
        const submission=submissions.find(s=>s.id===id);
        const challenge=challenges.find(ch=>ch.id===submission?.challenge_id);
        if(submission&&challenge){
          const {error:portfolioError}=await supabase.from("portfolio_items").insert({
            editor_id:submission.editor_id,
            title:challenge.brand+" — "+challenge.title,
            video_url:submission.storage_path,
            tags:["challenge-winner","commercial"],
            ai_score:submission.ai_score
          });
          if(portfolioError&&!portfolioError.message.includes("duplicate"))setMessage(portfolioError.message);
          else setMessage("Победитель выбран, а работа добавлена в его портфолио.");
        }
      }
    }
    setSubmissions(s=>s.map(x=>x.id===id?{...x,status}:x));
  }

  if(mode==="business"){
    return <div className="challenge-layout">
      <section className="card">
        <div className="eyebrow">НОВОЕ ЗАДАНИЕ</div>
        <h3>Создать реальное ТЗ</h3>
        {!businessVerified&&<div className="auth-msg">Публикация закрыта до проверки компании. Заполни блок «Проверка бизнеса» выше.</div>}
        <form className="business-form" onSubmit={createChallenge}>
          <input required placeholder="Название компании" value={form.brand} onChange={e=>setForm({...form,brand:e.target.value})}/>
          <input required placeholder="Название конкурса" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
          <textarea required placeholder="ТЗ: длительность, формат, обязательные элементы, ограничения..." value={form.brief} onChange={e=>setForm({...form,brief:e.target.value})}/><button type="button" className="btn btn-ghost" onClick={improveBrief} disabled={loadingBrief}>{loadingBrief?"AI структурирует…":"✨ Улучшить ТЗ с AI"}</button>
          <input type="url" placeholder="Ссылка на исходники / референсы (Drive, Disk, Dropbox…)" value={form.sourceUrl} onChange={e=>setForm({...form,sourceUrl:e.target.value})}/>
          <div className="split-fields"><input required min="0" type="number" placeholder="Приз, ₽" value={form.prize} onChange={e=>setForm({...form,prize:e.target.value})}/><input type="datetime-local" value={form.deadline} onChange={e=>setForm({...form,deadline:e.target.value})}/></div>
          <button className="btn btn-lime" disabled={loading||!businessVerified}>{loading?"Публикуем...":businessVerified?"Опубликовать в Arena":"Сначала пройти проверку"}</button>
        </form>
        {message&&<div className="auth-msg">{message}</div>}
      </section>

      <section className="card">
        <div className="eyebrow">РАБОТЫ УЧАСТНИКОВ</div>
        <h3>Работы участников</h3>
        {submissions.length===0?<p className="muted">Когда монтажёры отправят работы, они появятся здесь.</p>:<div className="submission-list">
          {submissions.map(s=><article className="submission submission-video" key={s.id}>
            <div className="submission-preview">{s.video_url?<video controls preload="metadata" src={s.video_url}/>:<div className="work-preview">VIDEO</div>}</div>
            <div className="submission-info"><b>{s.editor_name}</b><div><span className="tag">{s.status}</span>{s.ai_score!=null&&<span className="tag">AI {s.ai_score}</span>}</div></div>
            <div className="submission-actions"><button className="btn" onClick={()=>setSubmissionStatus(s.id,"shortlisted")}>В избранное</button><button className="btn btn-dark" onClick={()=>setSubmissionStatus(s.id,"winner")}>Победитель</button></div>
          </article>)}
        </div>}
      </section>
    </div>
  }

  if(role&&challenges.length===0){
    return <div className="card"><div className="eyebrow">ARENA</div><h3>Пока нет открытых заданий</h3><p className="muted">Когда бизнес опубликует первое реальное ТЗ, оно появится здесь. Демо-призы зарегистрированным пользователям не показываются.</p></div>
  }

  return <div className="challenge-layout">
    <section className="challenge-list">
      {challenges.map(c=><button key={c.id} className={"challenge-row "+(selected?.id===c.id?"active":"")} onClick={()=>{setSelectedId(c.id);setMessage("")}}>
        <div><span className="eyebrow">{c.brand}</span>{c.brand_verified&&<span className="tag verification-mini">{badgeName(c.verification_level)}</span>}<h3>{c.title}</h3></div>
        <div><b>{money(c.prize_cents)}</b><span className="muted">{deadline(c.ends_at)}</span></div>
      </button>)}
    </section>

    {selected&&<section className="card challenge-detail">
      <div className="eyebrow">ТЗ ОТ КОМПАНИИ</div>
      <h2>{selected.title}</h2>
      <div className="challenge-meta"><span>{selected.brand}</span>{selected.brand_verified&&<span className="tag verification-mini">{badgeName(selected.verification_level)}</span>}<b>{money(selected.prize_cents)}</b><span>{deadline(selected.ends_at)}</span></div>
      <p>{selected.brief}</p>
      {selected.source_assets.length>0&&<div className="source-assets"><b>Исходники:</b>{selected.source_assets.map((url,i)=><a key={i} href={url} target="_blank" rel="noreferrer">Открыть материалы ↗</a>)}</div>}
