"use client";

import { FormEvent, useState } from "react";
import { extractVideoFrames } from "@/lib/video-frames";
import { getSupabaseBrowserClient } from "@/lib/supabase-browser";

type Review = {
  overall_score: number;
  hook_score: number;
  pacing_score: number;
  subtitles_score: number;
  visual_variety_score: number;
  brief_match_score: number;
  format_score: number;
  technical_checks?: Array<{label:string;status:"ok"|"warn";detail:string}>;
  summary: string;
  strengths: string[];
  timeline: Array<{
    timecode: string;
    issue: string;
    fix: string;
  }>;
  next_steps: string[];
};

export default function VideoReview() {
  const [file, setFile] = useState<File | null>(null);
  const [brief, setBrief] = useState("");
  const [status, setStatus] = useState("");
  const [review, setReview] = useState<Review | null>(null);
  const [loading, setLoading] = useState(false);
  const [isDemo, setIsDemo] = useState(false);

  async function submit(e: FormEvent) {
    e.preventDefault();
    if (!file || loading) return;

    setLoading(true);
    setReview(null);
    setIsDemo(false);

    try {
      setStatus("Извлекаю ключевые кадры из видео…");
      const extracted = await extractVideoFrames(file, 7);

      setStatus("AI анализирует hook, pacing, субтитры и соответствие брифу…");
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      const token=session?.access_token;
      if(!token)throw new Error("Войди в аккаунт с AI PRO, чтобы запустить разбор.");

      const response = await fetch("/api/ai/video-review", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization:"Bearer "+token
        },
        body: JSON.stringify({
          frames: extracted.frames,
          duration: extracted.duration,
          brief,
          filename: file.name,
          purpose: "standalone",
        }),
      });

      const data = await response.json();
      if (!response.ok) {
        throw new Error(data?.error || "Не удалось выполнить AI-разбор.");
      }

      setReview(data.review);
      setIsDemo(Boolean(data.demo));
      setStatus("");
    } catch (error) {
      setStatus(
        error instanceof Error
          ? error.message
          : "Не удалось разобрать видео. Попробуй другой файл."
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="review-layout">
      <section className="card review-upload">
        <div className="eyebrow">AI РАЗБОР ВИДЕО</div>
        <h2>Загрузи ролик — получи разбор по таймкодам</h2>
        <p className="muted">
          Видео обрабатывается в браузере: EDITA извлекает несколько кадров и
          отправляет AI только эти кадры, таймкоды и бриф. Полный видеофайл в AI
          endpoint не отправляется.
        </p>

        <form className="review-form" onSubmit={submit}>
          <label className="review-file">
            <span>{file ? file.name : "Выбрать MP4 / MOV / WebM"}</span>
            <input
              type="file"
              accept="video/mp4,video/quicktime,video/webm,video/*"
              onChange={(e) => {
                setFile(e.target.files?.[0] || null);
                setReview(null);
                setStatus("");
              }}
            />
          </label>

          <textarea
            value={brief}
            onChange={(e) => setBrief(e.target.value)}
            placeholder="Необязательно: вставь ТЗ клиента. Например: Reel 25 секунд, премиальный стиль, показать продукт в первые 3 секунды, CTA в конце."
          />

          <button className="btn btn-dark" disabled={!file || loading}>
            {loading ? "Анализируем…" : "Запустить AI Review"}
          </button>
        </form>

        {status && <div className="auth-msg">{status}</div>}
      </section>

      <section className="review-result">
        {!review ? (
          <div className="review-empty">
            <div className="review-empty-score">AI</div>
            <h3>Здесь появится scorecard</h3>
            <p className="muted">
              Overall, Hook, Pacing, Subtitles, Visual Variety, Brief Match и
              конкретные правки по таймкодам.
            </p>
          </div>
        ) : (
          <>
            {isDemo && (
              <div className="demo-banner">
                Demo-анализ: Vercel пока не передал OPENAI_API_KEY в этот
                deployment.
              </div>
            )}

            <div className="score-hero">
              <div className="score-ring">
                <strong>{review.overall_score}</strong>
                <span>/100</span>
              </div>
              <div>
                <div className="eyebrow">EDITA SCORE</div>
                <h2>{scoreLabel(review.overall_score)}</h2>
                <p>{review.summary}</p>
              </div>
            </div>

            <div className="score-grid">
              <Score label="Hook" value={review.hook_score} />
              <Score label="Pacing" value={review.pacing_score} />
              <Score label="Subtitles" value={review.subtitles_score} />
              <Score label="Visual variety" value={review.visual_variety_score} />
              <Score label="Brief match" value={review.brief_match_score} />
              <Score label="Format" value={review.format_score} />
            </div>

            <div className="card review-section">
              <div className="eyebrow">TECHNICAL</div>
              <h3>Проверка файла</h3>
              <div className="technical-list">
                {(review.technical_checks||[]).map((item,i)=><div className={"technical-row "+item.status} key={i}><b>{item.status==="ok"?"✓":"!"} {item.label}</b><span>{item.detail}</span></div>)}
              </div>
            </div>

            <div className="card review-section">
              <div className="eyebrow">STRENGTHS</div>
              <h3>Что уже работает</h3>
              <div className="review-list">
                {review.strengths.map((item, i) => (
                  <div key={i} className="review-positive">
                    <span>✓</span>
                    <p>{item}</p>
                  </div>
                ))}
              </div>
            </div>

            <div className="card review-section">
              <div className="eyebrow">TIMELINE</div>
              <h3>Что поправить в монтаже</h3>
              <div className="timeline-list">
                {review.timeline.map((item, i) => (
                  <article className="timeline-item" key={i}>
                    <time>{item.timecode}</time>
                    <div>
                      <b>{item.issue}</b>
                      <p>{item.fix}</p>
                    </div>
                  </article>
                ))}
              </div>
            </div>

            <div className="card review-section">
              <div className="eyebrow">NEXT MOVE</div>
              <h3>Следующие действия</h3>
              <ol className="next-list">
                {review.next_steps.map((item, i) => (
                  <li key={i}>{item}</li>
                ))}
              </ol>
            </div>
          </>
        )}
      </section>
    </div>
  );
}

function Score({ label, value }: { label: string; value: number }) {
  return (
    <div className="score-card">
      <div className="score-card-top">
        <span>{label}</span>
        <strong>{value}</strong>
      </div>
      <div className="score-track">
        <span style={{ width: Math.max(0, Math.min(100, value)) + "%" }} />
      </div>
    </div>
  );
}

function scoreLabel(value: number) {
  if (value >= 90) return "Почти production-ready";
  if (value >= 80) return "Сильная работа";
  if (value >= 70) return "Хорошая база";
  if (value >= 60) return "Нужна доработка";
  return "Сначала исправим фундамент";
}

import type {SupabaseClient} from "@supabase/supabase-js";

export type AiChatMessage={id?:string;from:"user"|"ai";text:string;createdAt?:string};

export function normalizeAiScope(value:unknown){
  const scope=String(value||"main").trim().toLowerCase().replace(/[^a-z0-9:_-]/g,"-").slice(0,100);
  return scope||"main";
}

export async function getOrCreateConversation(
  service:SupabaseClient,
  userId:string,
  scopeKey:string,
  title:string,
  lessonSlug?:string|null
){
  const scope=normalizeAiScope(scopeKey);
  const {data:existing}=await service.from("ai_conversations")
    .select("id,scope_key,title,lesson_slug,updated_at")
    .eq("user_id",userId)
    .eq("scope_key",scope)
    .maybeSingle();
  if(existing)return existing;

  const {data,error}=await service.from("ai_conversations").insert({
    user_id:userId,
    scope_key:scope,
    title:String(title||"AI Помощник").slice(0,120),
    lesson_slug:lessonSlug?String(lessonSlug).slice(0,120):null
  }).select("id,scope_key,title,lesson_slug,updated_at").single();
  if(error)throw error;
  return data;
}

export async function readConversationMessages(service:SupabaseClient,userId:string,conversationId:string,limit=80){
  const {data,error}=await service.from("ai_messages")
    .select("id,role,content,created_at")
    .eq("conversation_id",conversationId)
    .eq("user_id",userId)
    .order("created_at",{ascending:true})
    .limit(Math.max(1,Math.min(limit,120)));
  if(error)throw error;
  return (data||[]).map((row:any)=>({
    id:row.id,
    from:row.role==="assistant"?"ai":"user",
    text:row.content,
    createdAt:row.created_at
  })) as AiChatMessage[];
}

export async function saveConversationMessage(
  service:SupabaseClient,
  userId:string,
  conversationId:string,
  role:"user"|"assistant",
  content:string,
  metadata:Record<string,unknown>={}
){
  const safeContent=String(content).trim().slice(0,12000);
  if(!safeContent)return;
  const {error}=await service.from("ai_messages").insert({
    conversation_id:conversationId,
    user_id:userId,
    role,
    content:safeContent,
    metadata
  });
  if(error)throw error;
  await service.from("ai_conversations").update({updated_at:new Date().toISOString()}).eq("id",conversationId).eq("user_id",userId);
}

export function authErrorRu(message?:string|null){
  const value=(message||"").toLowerCase();

  if(value.includes("email rate limit exceeded")||value.includes("rate limit")){
    return "Слишком много писем было запрошено за короткое время. Подожди немного и попробуй ещё раз.";
  }
  if(value.includes("user already registered")){
    return "Аккаунт с этим email уже существует. Попробуй войти или восстановить пароль.";
  }
  if(value.includes("invalid login credentials")){
    return "Неверный email или пароль.";
  }
  if(value.includes("email not confirmed")){
    return "Email ещё не подтверждён. Открой письмо от EDITA или отправь подтверждение ещё раз.";
  }
  if(value.includes("password should be at least")){
    return "Пароль слишком короткий. Используй минимум 8 символов.";
  }
  if(value.includes("unable to validate email")||value.includes("invalid email")){
    return "Проверь email: похоже, в адресе есть ошибка.";
  }
  return message||"Что-то пошло не так. Попробуй ещё раз.";
}

type ModerationResult={allowed:boolean;reason?:"abuse"|"off_topic"|"personal_info";message?:string};

const abusivePattern=/(?:^|[^\p{L}\p{N}])(?:бл(?:я|ять|ядь)|сук(?:а|и|у|ой)?|х(?:у[йеяи]|ер)|пизд[\p{L}]*|(?:е|ё)б(?:ать|ан|уч|ло|нут)[\p{L}]*|fuck\w*|shit\w*|bitch\w*)(?=$|[^\p{L}\p{N}])/iu;
const emailPattern=/\b[^\s@]+@[^\s@]+\.[^\s@]+\b/i;
const phonePattern=/(?:\+?\d[\s().-]*){10,}/;
const editingTopicPattern=/(монтаж|видео|ролик|reels?|shorts?|tiktok|youtube|capcut|premiere|davinci|final cut|inshot|\bvn\b|canva|таймлайн|кадр|склейк|субтитр|звук|музык|эффект|переход|экспорт|съ[её]м|сценар|контент|портфолио|клиент|задани|урок|проект|групп)/iu;
const obviousOffTopicPattern=/(казино|ставк[аи]|букмекер|политик|выборы|президент|знакомств|встречаться|майнкрафт|minecraft|fortnite|ставьте деньги|продам аккаунт)/iu;

export async function moderateGroupMessage(raw:string):Promise<ModerationResult>{
  const text=raw.trim();
  if(abusivePattern.test(text))return {allowed:false,reason:"abuse",message:"Сообщение не отправлено: в учебном чате нельзя использовать оскорбления или мат."};
  if(emailPattern.test(text)||phonePattern.test(text))return {allowed:false,reason:"personal_info",message:"Не публикуй в группе email или номер телефона. Общайтесь внутри EDITA."};
  if(obviousOffTopicPattern.test(text)&&!editingTopicPattern.test(text))return {allowed:false,reason:"off_topic",message:"Это учебный чат про видео и совместные проекты. Переформулируй сообщение по теме монтажа."};
  if(!process.env.OPENAI_API_KEY)return {allowed:true};

  try{
    const response=await fetch("https://api.openai.com/v1/responses",{
      method:"POST",
      headers:{"Content-Type":"application/json",Authorization:`Bearer ${process.env.OPENAI_API_KEY}`},
      body:JSON.stringify({
        model:process.env.OPENAI_MODEL||"gpt-5.6-luna",
        instructions:"Ты классификатор сообщений закрытой учебной группы по видеомонтажу для аудитории 14+. Ответь только одним токеном: ALLOW, OFF_TOPIC, ABUSE или PERSONAL_INFO. Разрешай монтаж, съёмку, контент, обучение, портфолио, клиентов, совместный проект, дружелюбное приветствие и поддержку. OFF_TOPIC — явный уход в постороннюю тему. ABUSE — мат, травля, унижение, сексуальные домогательства или угрозы. PERSONAL_INFO — просьба или попытка передать телефон, email, адрес либо встретиться вне платформы.",
        input:text.slice(0,1400),
        max_output_tokens:20
      }),
      signal:AbortSignal.timeout(8000)
    });
    if(!response.ok)return {allowed:true};
    const data=await response.json();
    const label=String(data.output_text||"").trim().toUpperCase();
    if(label.includes("ABUSE"))return {allowed:false,reason:"abuse",message:"Сообщение не отправлено: общайтесь без оскорблений и травли."};
    if(label.includes("PERSONAL_INFO"))return {allowed:false,reason:"personal_info",message:"Сообщение не отправлено: не передавайте личные контакты внутри учебной группы."};
    if(label.includes("OFF_TOPIC"))return {allowed:false,reason:"off_topic",message:"Это учебный чат про видео и совместные проекты. Переформулируй сообщение по теме монтажа."};
    return {allowed:true};
  }catch{
    return {allowed:true};
  }
}

export async function createGroupAiReply(question:string,recent:string[]){
  if(!process.env.OPENAI_API_KEY)return "Я рядом. Напишите, в какой программе вы работаете и на каком шаге остановились — подскажу короткий путь.";
  try{
    const response=await fetch("https://api.openai.com/v1/responses",{
      method:"POST",
      headers:{"Content-Type":"application/json",Authorization:`Bearer ${process.env.OPENAI_API_KEY}`},
      body:JSON.stringify({
        model:process.env.OPENAI_MODEL||"gpt-5.6-luna",
        instructions:"Ты EDITA AI в безопасной учебной группе по видеомонтажу для людей 14+. Отвечай только по монтажу, съёмке, контенту, портфолио и совместной работе. Не поддерживай переход в личные контакты. Дай прямой ответ, 2–5 коротких шагов и один способ проверить результат. Не стыди новичка, не обещай доход или просмотры. Не повторяй и не раскрывай личные данные.",
        input:"Недавний контекст группы:\n"+recent.slice(-8).join("\n")+"\n\nВопрос к EDITA AI:\n"+question.slice(0,1400),
        max_output_tokens:700
      }),
      signal:AbortSignal.timeout(20000)
    });
    if(!response.ok)throw new Error("upstream");
    const data=await response.json();
    return String(data.output_text||"").trim()||"Не получилось подготовить ответ. Попробуйте спросить ещё раз чуть позже.";
  }catch{
    return "Сейчас не могу подготовить подробный ответ. Напишите программу, устройство и точный шаг — вернёмся к вопросу чуть позже.";
  }
}

