import {NextRequest,NextResponse} from "next/server";

const ACCESS_HASH="bfc66c41fc002c17d37c9649cce339179454851d26591ccae64b489df56ff3e1";

async function sha256(value:string){
  const bytes=new TextEncoder().encode(value);
  const digest=await crypto.subtle.digest("SHA-256",bytes);
  return Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,"0")).join("");
}

export default async function proxy(req:NextRequest){
  const path=req.nextUrl.pathname;
  if(process.env.NODE_ENV==="development"&&req.nextUrl.hostname==="127.0.0.1"){
    return NextResponse.next();
  }
  if(
    path==="/prelaunch"||
    path==="/api/prelaunch"||
    path==="/api/email/health"||
    path.startsWith("/_next/")||
    path==="/favicon.ico"||
    path==="/robots.txt"
  ){
    return NextResponse.next();
  }

  const code=req.cookies.get("edita_prelaunch")?.value||"";
  if(code && await sha256(code)===ACCESS_HASH){
    return NextResponse.next();
  }

  if(path.startsWith("/api/")){
    return NextResponse.json({error:"EDITA сейчас в закрытом предзапуске."},{status:401});
  }

  const url=req.nextUrl.clone();
  url.pathname="/prelaunch";
  url.searchParams.set("from",path==="/"?"/review-access":path);
  return NextResponse.redirect(url);
}

export const config={
  matcher:["/((?!.*\\.(?:png|jpg|jpeg|gif|svg|webp|ico|css|js|map|woff2?)$).*)"]
};

import {Resend} from "resend";

const apiKey=process.env.RESEND_API_KEY;
const to=process.argv[2];

if(!apiKey||apiKey==="re_xxxxxxxxx"){
  throw new Error("Replace re_xxxxxxxxx with your real Resend API key in RESEND_API_KEY.");
}

if(!to){
  throw new Error("Pass the recipient: npm run email:test -- you@example.com");
}

const resend=new Resend(apiKey);
const {data,error}=await resend.emails.send({
  from:"onboarding@resend.dev",
  to,
  subject:"Hello World",
  html:"<p>Congrats on sending your <strong>first email</strong>!</p>",
});

if(error)throw new Error(error.message);

console.log("Email sent:",data?.id);

